function detectDesktopNativeLocale(languages) {
  for (const language of languages) {
    const source = locale(language);
    if (!source) continue;
    if (["no", "nb", "nn"].includes(source.language)) return "no";
    const match2 = DESKTOP_NATIVE_LOCALES.find((candidate) => {
      const target2 = locale(DESKTOP_NATIVE_LOCALE_TAGS[candidate]);
      return target2?.language === source.language && target2.script === source.script;
    });
    if (match2) return match2;
  }
  return "en";
}
function locale(value) {
  try {
    return new Intl.Locale(value).maximize();
  } catch {
    return void 0;
  }
}
