const DESKTOP_NATIVE_KEYS = Object.keys(DESKTOP_NATIVE_ENGLISH);
function createDesktopNativeBundle(locale2, translate) {
  return {
    locale: locale2,
    messages: Object.fromEntries(DESKTOP_NATIVE_KEYS.map((key2) => [key2, translate(key2)]))
  };
}
